-- 2026-11-09, user-directed: 'How it helps you' line per Risk Dial gauge (shown on the panel + popup), simplified
-- first-line descriptions, and the vrp_gone rename. Description = first line of ref_risk_gauge.help.

UPDATE ref_risk_gauge SET how_helps = 'Be careful buying more now. Think about selling some winners.' WHERE gauge_key = 'spx_top_range';
UPDATE ref_risk_gauge SET help = 'The S&P 500 is near the top of its expected range, so there is less room to rise.' || substr(help, position(E'\n' in help)) WHERE gauge_key = 'spx_top_range' AND position(E'\n' in help) > 0;
