-- Record-level warning distances (percent of the record) and whether the record LOW also counts.
UPDATE ref_record_level SET near_pct = 2, use_low = FALSE;
UPDATE ref_record_level SET near_pct = 5, use_low = TRUE WHERE market_key IN ('us2y','us10y','us3m','us30y');
UPDATE ref_record_level SET near_pct = 10, use_low = TRUE WHERE market_key IN ('vix','move');
UPDATE ref_record_level SET use_low = TRUE WHERE market_key IN ('dxy','wti');
